pub fn solve(input: Vec<char>) -> Vec<char> {
    // Map each digit character to its "good count".
    fn good_count(c: char) -> u32 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // Unreachable given the input constraints
        }
    }

    // We only care about the first two characters
    let first = input[0];
    let second = input[1];

    // Compute the product of their good counts
    let product = good_count(first) * good_count(second);

    // Convert the product to its decimal representation and collect into Vec<char>
    let mut output: Vec<char> = product.to_string().chars().collect();

    // Append the required newline character
    output.push('\n');

    output
}